import java.util.Scanner;
public class Main {
    public static void main (String[] args) {
	Scanner scan = new Scanner(System.in);
	int a, prime_num;
	String[] iList;
	while (scan.hasNext()) {
	    iList = scan.nextLine().split(" ");
	    a = Integer.parseInt(iList[0]);
	    prime_num = Integer.parseInt(iList[1]);
	    System.out.println(determineDigits(a+prime_num));
	}
    }
    static int determineDigits (int a) {
	int digits = 0;
	while (a > 0) {
	    digits ++;
	    a /= 10;
	}
	return digits;
    }
}

