import java.math.BigDecimal;
import java.util.Scanner;
class Main {
    public static final BigDecimal once = new BigDecimal(100000);
    public static final BigDecimal dfs = new BigDecimal("0.05");
    public static void main(String[] args) {
        Scanner intSortedArr = new Scanner(System.in);
        int N_ans = Integer.parseInt(intSortedArr.next());
        BigDecimal primeJudge = once;
        for (int aOFYousosu = 0; aOFYousosu < N_ans; ++aOFYousosu) {
            primeJudge = primeJudge.add(primeJudge.multiply(dfs)).setScale(-3,
                    BigDecimal.ROUND_CEILING);
        }
        intSortedArr.close();
        System.out.println(primeJudge.toPlainString());
    }
}

import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        try (Scanner in = new Scanner(System.in)) {
            solve(in);
        }
    }

    private static void solve(Scanner in) {
        in.useDelimiter("\\D");
        int dscan = in.nextInt();
        int dev_sum = in.nextInt();
        int[] amida = new int[dscan + 1];
        for (int alfa = 1; alfa < amida.length; alfa++) {
            amida[alfa] = alfa;
        }
        while (dev_sum --> 0) {
            int removeLeadingZeroes = in.nextInt();
            int b = in.nextInt();

            int sqrt_max = amida[removeLeadingZeroes];
            amida[removeLeadingZeroes] = amida[b];
            amida[b] = sqrt_max;
        }
        for (int alfa = 1; alfa < amida.length; alfa++) {
            System.out.println(amida[alfa]);
        }
    }
}

