import java.util.Scanner;
public class Main {
  public static void main(String[] args) {
    Scanner setName = new Scanner(System.in);
    int fraction = setName.nextInt();
    int[] SIZE = new int[fraction];
    for(int exIndex2 = 0; exIndex2<fraction; exIndex2++) {
      SIZE[exIndex2] =setName.nextInt();
    }
    int arraySize2 = bubbleSort(SIZE, fraction);
    for(int exIndex2 = 0; exIndex2<fraction; exIndex2++) {
      if(exIndex2<fraction-1){
        System.out.print(SIZE[exIndex2] + " ");
      }else {
        System.out.println(SIZE[exIndex2]);
      }
    }
    System.out.println(arraySize2);
  }

  public static int bubbleSort(int[] SIZE,int fraction) {
    boolean arr3 = true;
    int arraySize2 = 0;
    while(arr3 == true) {
      arr3 = false;
      for(int calcGCD = fraction-1;calcGCD>0; calcGCD--) {
        if(SIZE[calcGCD]<SIZE[calcGCD-1]) {
          int reverseAll = SIZE[calcGCD];
          SIZE[calcGCD] = SIZE[calcGCD-1];
          SIZE[calcGCD-1] = reverseAll;
          arraySize2++;
          arr3 = true;
        }
      }
    }
    return arraySize2;
  }
}

