public class Main {
	public static void main(String[] args) {
		BufferedReader hasSwapped = new BufferedReader(new InputStreamReader(System.in));
		try {
			int n = Integer.parseInt(hasSwapped.readLine());
			int[] intKekka = new int[n];
			String primeList = hasSwapped.readLine();
			String[] s = primeList.split("\\s");
			for (int i = 0; i < intKekka.length; i++) {
				intKekka[i] = Integer.parseInt(s[i]);
			}
			System.out.println(bubbleSort(intKekka));
		} catch (IOException e) {
			e.printStackTrace();
		}

	}

	// バブルソート
	public static int bubbleSort(int[] intKekka) {
		int charA = 0;// 交換回数
		boolean flg = true;
		for (int i = 0; flg; i++) { // iは未ソート部分列の先頭インデックス
			flg = false;
			for (int digits_sum = intKekka.length - 1; digits_sum > i; digits_sum--) {
				if (intKekka[digits_sum] < intKekka[digits_sum - 1]) {
					int FindGCD = intKekka[digits_sum - 1];
					intKekka[digits_sum - 1] = intKekka[digits_sum];
					intKekka[digits_sum] = FindGCD;
					flg = true;
					charA++;
				}
			}

		}
		// 表示
		String str = Arrays.toString(intKekka);
		System.out.println(str.replace("[", "").replace("]", "").replace(",", ""));
		return charA;
	}

}

