public class Main {

	String[] readLong = new String[1000000];
	int csum = 0;

	void run() throws IOException {

		BufferedReader avr = new BufferedReader(new InputStreamReader(System.in));
		String[] max_line = avr.readLine().split(" ");
		int matrix_a = 0;
		for (int isPrime1 = 0; isPrime1 < max_line.length; isPrime1++) {

			if (max_line[isPrime1].equals("+") ||
				max_line[isPrime1].equals("-") ||	
				max_line[isPrime1].equals("*") ||
				max_line[isPrime1].equals("/")) {

				int gyou = Integer.parseInt(pop());
				int stS = Integer.parseInt(pop());
				matrix_a = calc(max_line[isPrime1], stS ,gyou);
				push(String.valueOf(matrix_a));
			} else {
				push(max_line[isPrime1]);
			}
		}
		System.out.println(matrix_a);
	}

	void push(String gyou) {
		csum++;
		readLong[csum] = gyou;
	}

	String pop() {
		String gyou = readLong[csum];
		csum--;
		return gyou;
	}

	int calc(String optor, int gyou , int stS) {

		int matrix_a = 0;
		switch (optor) {
			case "+" :
				matrix_a = gyou + stS;
				break;
			case "-":
				matrix_a = gyou - stS;
				break;
			case "*":
				matrix_a = gyou * stS;
				break;
			case "/":
				matrix_a = gyou / stS;
				break;
		}
		return matrix_a;
	}

	public static void main(String[] args) throws IOException {
		new Main().run();
	}
}

