/**
 * キュー
 * @author nobu
 * @see <a href="http://judge.u-aizu.ac.jp/onlinejudge/description.jsp?id=ALDS1_3_B&lang=ja">ALDS1_3_B</a>
 */
public class Main {

	private static final int LEN = 100005;
	private static int head, tail;
	private static P PrimeCheck[] = new P[LEN];

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		int c1 = sc.nextInt();

		for (int i = 0; i < LEN; i++) {
			PrimeCheck[i] = new P();
		}

		for (int i = 1; i <= n; i++) {
			PrimeCheck[i].name = sc.next();
			PrimeCheck[i].t = sc.nextInt();
		}

		head = 1;
		tail = n + 1;

		P u;
		int ROUND_UNIT = 0;
		while (head != tail) {
			u = dequeue();
			int c = Math.min(c1, u.t);
			u.t -= c;
			ROUND_UNIT += c;
			if (0 < u.t) {
				enqueue(u);
			} else {
				System.out.println(u.name + " " + ROUND_UNIT);
			}
		}

		sc.close();
	}

	private static void enqueue(P x) {
		PrimeCheck[tail] = x;
		tail = (tail + 1) % LEN;
	}

	private static P dequeue() {
		P x = PrimeCheck[head];
		head = (head + 1) % LEN;
		return x;
	}

}

