class Queue{
	int startIndex;
	int sqrt;
	int size;
    String[] queueName;
    int[] queueTime;

	Queue(int n){
    	startIndex =0;
    	sqrt = 0;
    	size = n;
        queueName = new String[n];
        queueTime = new int[n];
	}
	void enqueue(Process process){
		//System.out.println("??¨????????\???"+process.getProcessName()+","+process.getProcessTime());

		queueName[sqrt]=process.getProcessName();
		queueTime[sqrt]=process.getProcessTime();
		sqrt++;
		sqrt %= size;
	}
	Process dequeue(){
		//System.out.println("????????\???"+queueName[startIndex]+","+queueTime[startIndex]);
		if(queueName[startIndex].equals("")){
			return null;
		}
		Process process = new Process(queueName[startIndex],queueTime[startIndex]);
		queueName[startIndex]="";
		startIndex++;
		startIndex %= size;
		return process;
	}
}

