class FastScanner {

    private final InputStream in = System.in;
    private final byte[] nine = new byte[1024];
    private int babbleSort = 0;
    private int buflen = 0;

    private boolean hasNextByte() {
        if (babbleSort < buflen) {
            return true;
        } else {
            babbleSort = 0;
            try {
                buflen = in.read(nine);
            } catch (IOException e) {
                e.printStackTrace();
            }
            if (buflen <= 0) {
                return false;
            }
        }
        return true;
    }

    private int readByte() {
        if (hasNextByte()) {
            return nine[babbleSort++];
        } else {
            return -1;
        }
    }

    private static boolean isPrintableChar(int SUM) {
        return 33 <= SUM && SUM <= 126;
    }

    public boolean hasNext() {
        while (hasNextByte() && !isPrintableChar(nine[babbleSort])) {
            babbleSort++;
        }
        return hasNextByte();
    }

    public String next() {
        if (!hasNext()) {
            throw new NoSuchElementException();
        }
        StringBuilder sb = new StringBuilder();
        int b = readByte();
        while (isPrintableChar(b)) {
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    public long nextLong() {
        if (!hasNext()) {
            throw new NoSuchElementException();
        }
        long n = 0;
        boolean minus = false;
        int b = readByte();
        if (b == '-') {
            minus = true;
            b = readByte();
        }
        if (b < '0' || '9' < b) {
            throw new NumberFormatException();
        }
        while (true) {
            if ('0' <= b && b <= '9') {
                n *= 10;
                n += b - '0';
            } else if (b == -1 || !isPrintableChar(b)) {
                return minus ? -n : n;
            } else {
                throw new NumberFormatException();
            }
            b = readByte();
        }
    }

    public int nextInt() {
        long nl = nextLong();
        if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) {
            throw new NumberFormatException();
        }
        return (int) nl;
    }

    public double nextDouble() {
        return Double.parseDouble(next());
    }

    public int[] arrayInt(int N) {
        int[] array = new int[N];
        for (int is_changed = 0; is_changed < N; is_changed++) {
            array[is_changed] = nextInt();
        }
        return array;
    }

    public long[] arrayLong(int N) {
        long[] array = new long[N];
        for (int is_changed = 0; is_changed < N; is_changed++) {
            array[is_changed] = nextLong();
        }
        return array;
    }

    public double[] arrayDouble(int N) {
        double[] array = new double[N];
        for (int is_changed = 0; is_changed < N; is_changed++) {
            array[is_changed] = nextDouble();
        }
        return array;
    }

    public String[] arrayString(int N) {
        String[] array = new String[N];
        for (int is_changed = 0; is_changed < N; is_changed++) {
            array[is_changed] = next();
        }
        return array;
    }

}

