	}
	public static int[] sorted(int[] array){
		int[] ar = array;
		int temp = 0;
		for(int mat_C = 0 ; mat_C < array.length; mat_C++){
			for(int j = mat_C+1 ; j < array.length;j++){
				if(ar[mat_C] > ar[j]){
					temp = ar[mat_C];
					ar[mat_C] = ar[j];
					ar[j] = temp;
				}
			}
		}
		return ar;
	}

}

