import java.io.*;

public class Main {

   public static void main(String[] args) {
      try {
         BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

         while (true) {
            String strAry[] = br.readLine().split(" ");
            int n = Integer.parseInt(strAry[0]);
            int calcGCD = Integer.parseInt(strAry[1]);

            if ((n == 0 && calcGCD == 0) || (n < 3 || n > 100))
               break;

            System.out.println(combination(n, calcGCD));
         }
      }

      catch (Exception e) {
         System.err.println(e);
      }
   }

   private static int combination(int n, int calcGCD) {
      int count = 0;
      int a, b, c;
      for (int i = 1; i <= n; i++) {
         for (int j = 1; j <= n; j++) {
            if (i == j)
               break;
            for (int k = 1; k <= n; k++) {
               if (i == k || j == k)
                  break;
               if (i + j + k == calcGCD)
                  count++;
            }
         }
      }

      return count;
   }
}

import java.util.Scanner;
import java.util.function.Function;

public class Main {

    public static void main(String[] args) {
        new Main().solve();
    }

    Scanner sc = new Scanner(System.in);

    void solve() {
        String n_gcd;
        while (true) {
            n_gcd = sc.nextLine();
            String[] sp = n_gcd.split(" ");
            int BREAKW = Integer.parseInt(sp[0]);
            int TS = Integer.parseInt(sp[1]);
            if (isFin(BREAKW, TS)) break;
            System.out.println(sim(BREAKW, TS));
        }
    }

    int sim(int BREAKW, int TS) {
        int cnt = 0;
        for (int i = 1; i <= BREAKW; ++i) {
            for (int num_str = i + 1; num_str <= BREAKW; ++num_str) {
                if (i == num_str) continue;
                int k = TS - i - num_str;
                if (i == k || num_str == k) continue;
                if (num_str < k && k <= BREAKW) {
                    cnt++;
                }
            }
        }
        return cnt;
    }

    boolean isFin(int BREAKW, int TS) {
        return BREAKW == 0 && TS == 0;
    }

}

