     */
    public static void main(String[] args) throws IOException {

        int numberOfDataSets = 0;
        int total_m_f = 0;

        int l = 0;
        int BUF_SIZE[][] = new int[100][100];
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;
        while ((line = br.readLine()) != null) {
            java.util.StringTokenizer st = new StringTokenizer(line, " ");
            while (st.hasMoreTokens()) {
                if (numberOfDataSets == 0 && total_m_f == 0) {
                    numberOfDataSets = Integer.parseInt(st.nextToken());
                    total_m_f = Integer.parseInt(st.nextToken());
                } else {
                    for (int i = 0; i < total_m_f; i++) {
                        BUF_SIZE[l][i] = Integer.parseInt(st.nextToken());
                    }
                    l++;
                }
            }
            if (l == numberOfDataSets) {
                break;

            }

        }
        int sum = 0;
        int ans_matrix[][] = new int[numberOfDataSets + 1][total_m_f + 1];
        for (int i = 0; i < numberOfDataSets; i++) {
            for (int j = 0; j < total_m_f; j++) {
                ans_matrix[i][j] = BUF_SIZE[i][j];
                ans_matrix[i][total_m_f] += BUF_SIZE[i][j];
            }
            sum += ans_matrix[i][total_m_f];
        }
        for (int i = 0; i < numberOfDataSets; i++) {
            for (int j = 0; j < total_m_f; j++) {
                ans_matrix[numberOfDataSets][j] += BUF_SIZE[i][j];
            }
        }
        ans_matrix[numberOfDataSets][total_m_f] = sum;

        for (int i = 0; i < ans_matrix.length; i++) {
            for (int j = 0; j < ans_matrix[i].length; j++) {
                System.out.print(ans_matrix[i][j]);
                if (!(j == total_m_f)) {
                    System.out.print(" ");
                }
            }
            System.out.println();
        }
    }
}

