	public static void main(String args[]){
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		int m = sc.nextInt();
		int pm = sc.nextInt();
		long[][] a = new long[100][101];
		long[][] b = new long[101][100];
		long[][] elapsed_time = new long[100][100];
		int i  = 0;
		int max  = 0;
		int rauzu  = 0;

		for(i = 0; i < n; i++) {
			for(rauzu = 1; rauzu <= m; rauzu++) {
				a[i][rauzu] = sc.nextInt();
			}
		}

		for(rauzu = 1; rauzu <= m; rauzu++) {
			for(max = 0; max < pm; max++) {
				b[rauzu][max] = sc.nextInt();
			}
		}

		for(i = 0; i < n; i++) {
			for(max = 0; max < pm; max++) {
				for(rauzu = 1; rauzu <= m; rauzu++) {
					elapsed_time[i][max] += a[i][rauzu] * b[rauzu][max];
				}
				if(max < pm-1) {
					System.out.print(elapsed_time[i][max] + " ");
				}else {
					System.out.print(elapsed_time[i][max]);
				}
			}
			System.out.println();
		}
		sc.close();
	}
}

