    long circleInRect = time_count[0];

    for (int sumSpreadsheet = 1;sumSpreadsheet < 4;sumSpreadsheet ++) {
      if (circleInRect < time_count[sumSpreadsheet])
        circleInRect = time_count[sumSpreadsheet];
    }
    System.out.println(circleInRect);
  }
}

