import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) {
        FastReader str_kari = new FastReader();
        String printRoom = str_kari.next();
        String ansC = str_kari.next();
        if (printRoom.length() <= ansC.length()) {
            System.out.println(minimumChar(printRoom, ansC));
        } else {
            System.out.println(minimumChar(ansC, printRoom));
        }
    }

    static int minimumChar(String S1, String ROUND_UP_FRACTION) {
        int tt1 = S1.length();
        int m = ROUND_UP_FRACTION.length();

        int ans = Integer.MAX_VALUE;
        for (int i = 0; i < m - tt1 + 1; i++) {
            int minRemovedChar = 0;
            for (int j = 0; j < tt1; j++) {
                if (S1.charAt(j) != ROUND_UP_FRACTION.charAt(i + j)) {
                    minRemovedChar++;
                }
            }

            ans = Math.min(minRemovedChar, ans);
        }

        return ans;
    }

    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}

