import java.util.Scanner;

public class Main {

	static int solve(String runProcessing, String MAX_B) {
		int route = 1001;

		for (int c_name = 0; c_name < runProcessing.length() - MAX_B.length() + 1; c_name++) {
			int count = 0;
			for (int j = 0; j < MAX_B.length(); j++) {
				if (runProcessing.charAt(c_name + j) != MAX_B.charAt(j))
					count++;
			}
			if (count < route)
				route = count;
		}

		return route;
	}

	public static void main(String[] args) {
		Scanner stdIn = new Scanner(System.in);

		String runProcessing, MAX_B;
		runProcessing = stdIn.next();
		MAX_B = stdIn.next();
		int result = solve(runProcessing, MAX_B);
