public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter isPrimeNumber = new PrintWriter(outputStream);
        Task solver = new Task();
        solver.solve(in, isPrimeNumber);
        isPrimeNumber.close();
    }
    // main solver
    static class Task{
        public void solve(InputReader in, PrintWriter isPrimeNumber) {
            int suzuki = in.nextInt();
            if (suzuki % 1000 == 0){
                isPrimeNumber.println(0);
            }
            else{
                isPrimeNumber.println(1000 - (suzuki % 1000));
            }
        }
    }
    // fast input reader class;
    static class InputReader {
        BufferedReader br;
        StringTokenizer st;

        public InputReader(InputStream stream) {
            br = new BufferedReader(new InputStreamReader(stream));
        }

        public String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                String line = null;
                try {
                    line = br.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
                if (line == null) {
                    return null;
                }
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(nextToken());
        }
        public long nextLong(){
            return Long.parseLong(nextToken());
        }
    }
}

