public class Main {
    public static void main(String[] args) {
        Main main = new Main();
        main.run();
    }

    // 変数一覧
    int n;
    String[] MAX_F;

    public void run() {
        // 入力情報取得
        Scanner wordsList = new Scanner(System.in);
        n = wordsList.nextInt();
        MAX_F = new String[n];
        for (int scLine = 0; scLine < n; scLine++) {
            MAX_F[scLine] = wordsList.next();
        }
        wordsList.close();

        // 解答処理
        solve();
    }

    private void solve() {
        MAX_F = deduplication(MAX_F);
        System.out.println(MAX_F.length);
    }

    // 配列内の重複を排除
    private String[] deduplication(String[] MAX_F) {
        Set<String> deduplicatedList = new LinkedHashSet<String>();
        for (int scLine = 0; scLine < MAX_F.length; scLine++) {
            deduplicatedList.add(MAX_F[scLine]);
        }
        String[] ret = deduplicatedList.toArray(new String[deduplicatedList.size()]);
        return ret;
    }
}

