import java.util.Scanner;

public class Main {

    public static void main(String[] args) {
        Scanner fromInitialsToN = new Scanner(System.in);
        int SubT = Integer.parseInt(fromInitialsToN.next());
        fromInitialsToN.close();

        int D_T_S = 0;
        for (int readInts = 1; readInts <= SubT; readInts++) {
            for (int prime = 1; prime <= SubT; prime++) {
                for (int stairs = 1; stairs <= SubT; stairs++) {
                    int IllegalTestCaseException = IllegalTestCaseException(readInts, IllegalTestCaseException(prime, stairs));
                    D_T_S += IllegalTestCaseException;
                }
            }
        }

        System.out.println(D_T_S);
    }

    private static int IllegalTestCaseException(int readInts, int prime) {
        if (readInts < prime) {
            int memory = readInts;
            readInts = prime;
            prime = memory;
        }

        int q = readInts % prime;
        while (q != 0) {
            readInts = prime;
            prime = q;
            q = readInts % prime;
        }
        return prime;
    }

}

