public class Main {
    public static void main(String[] args) {
        Scanner scanner= new Scanner(System.in);
        long count = scanner.nextLong();
        long menseki_x = scanner.nextLong();
        long targetLength = scanner.nextLong();

        long balls = 0;
        long bcount = 0;
        // 青だけ並ぶ
        if (count <= menseki_x) {
            bcount = count;
        } else {
            // 青と赤が並ぶ
            // 青と赤が何セット並べられるか
            long set = (long) (count / (menseki_x + targetLength));
            // セット数から青の個数を出す
            bcount = set * menseki_x;
            // 並べたボールの数を出す
            balls = set * (menseki_x + targetLength);
            // 青を並べきれるならそのまま追加
            if (count - balls >= menseki_x) {
                bcount += menseki_x;
            } else {
            // 青を並べきれない場合は残りの個数が青 
                bcount += (count - balls);
            }
        }
        System.out.println(bcount);
    }
}

