public class Main{
	public static void main(String args[]){
		Scanner elements_A_array = new Scanner(System.in);
		String capacity = elements_A_array.next();
		long weight = Long.parseLong(capacity);
		String det = elements_A_array.next();
		long CMD = Long.parseLong(det);
		String duration = elements_A_array.next();
		long createArray = Long.parseLong(duration);
		long ans;
		long mult = weight / (CMD + createArray);
		long ex = weight - (CMD + createArray) * mult;
		if(CMD == 0){
			ans = 0;
		}else{
			ans = mult * CMD;
			if(ex <= CMD){
				ans += ex;
			}else{
				ans += CMD;
			}
		}
		System.out.println(ans);
	}
}

