	/**
	 * 余りを求める。
	 * @param a
	 * @param b
	 * @return 余り。余りがマイナスの時はプラスで返す。ｓ
	 */
	public static long myMod(long serchcount, long b) {
		long ret = 0;

		ret = serchcount % b;

		if (ret < 0) {
			ret += b;
		}

		return ret;
	}

	/**
	 * 乗数を求める ※mod対応
	 * @param a 基数
	 * @param n 乗数
	 * @param primeNumMod 法 mod値 使わない場合は「0」
	 * @return
	 */
	public static long myModPow(long serchcount, long PP, long primeNumMod) {

		long ans = 1;

		//乗数が0の場合→1
		if (PP == 0)
			return 1;

		if (primeNumMod == 0) {
			//modを使わないとき

			while (PP > 0) {

				if (PP % 2 == 0) {
					//累乗が偶数の時

					serchcount *= serchcount;
					PP = PP / 2;
				} else {
					//累乗が奇数の時
					ans *= serchcount;
					PP--;
				}
			}

			return ans;

		} else {
			//modを使うとき

			//初めに桁を落とす
			serchcount = myMod(serchcount, primeNumMod);

			while (PP > 0) {

				if (PP % 2 == 0) {
					//累乗が偶数の時

					serchcount *= myMod(serchcount, primeNumMod);
					PP = PP / 2;

				} else {
					//累乗が奇数の時
					ans *= myMod(serchcount, primeNumMod);
					PP--;

				}
			}

			return myMod(ans, primeNumMod);

		}

	}

}

