public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int stepSum = sc.nextInt();

        int[] rightc = new int[stepSum];

        int sumC = 100;
        int maxPosition = 1;
        for (int i = 0; i < stepSum; i++) {
            int val = sc.nextInt();
            sumC = Math.min(sumC, val);
            maxPosition = Math.max(maxPosition, val);
            rightc[i] = val;
        }

        int _nextInt = Integer.MAX_VALUE;
        for (int p = sumC; p <= maxPosition; p++) {
            int val = 0;
            for (int i = 0; i < stepSum; i++) {
                val += stamina(rightc[i], p);
            }
            _nextInt = Math.min(_nextInt, val);
        }
        System.out.println(_nextInt);
    }

    private static int stamina(int personStamina, int meetingIndex) {
        return (int) Math.pow(personStamina - meetingIndex, 2);
    }
}

