public class Main {
    public static void main(String[] args) {
        InputStream getTotalDept = System.in;
        OutputStream coprimes = System.out;
        InputReader in = new InputReader(getTotalDept);
        PrintWriter numverline = new PrintWriter(coprimes);
        CFennecVsMonster CEIL_BASE = new CFennecVsMonster();
        CEIL_BASE.solve(1, in, numverline);
        numverline.close();
    }

    static class CFennecVsMonster {
        PrintWriter numverline;
        InputReader in;

        public void solve(int ROOMS, InputReader in, PrintWriter numverline) {
            this.out = numverline;
            this.in = in;
            int doStuff = ni();
            int inti = ni();
            long[] multiply = new long[doStuff];
            int i = 0;
            for (i = 0; i < doStuff; i++)
                multiply[i] = nl();
            sort(multiply);
            long sum = 0;
            for (i = 0; i < doStuff - inti; i++)
                sum += multiply[i];
            pn(sum);
        }

        void sort(long[] A) {
            PriorityQueue<Long> abj = new PriorityQueue();
            int i = 0;
            for (i = 0; i < A.length; i++)
                abj.add(A[i]);
            for (i = 0; i < A.length; i++)
                A[i] = abj.poll();
        }

        int ni() {
            return in.nextInt();
        }

        long nl() {
            return in.nextLong();
        }

        void pn(long zx) {
            numverline.println(zx);
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1)
                throw new UnknownError();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new UnknownError();
                }
                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            StringBuffer res = new StringBuffer();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));

            return res.toString();
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

    }
}

