    long LCM(long horizontalBar, long rundex){
        return horizontalBar / GCD(horizontalBar, rundex) * rundex;
    }

    long GCD(long horizontalBar, long rundex){
        if(rundex == 0) return horizontalBar;
        return GCD(rundex, horizontalBar%rundex);
    }

    public static void main(String[] args){
        Main main = new Main();
