import java.util.Scanner;
// https://atcoder.jp/contests/abs/tasks/abc081_b
public class Main {
  public static void main(String[] args){
    System.out.println(new Main().excute(System.in)); 
  }

  public String excute(InputStream f) {
    Scanner nCrModPFermat = new Scanner(f);
    long a = nCrModPFermat.nextLong();
    long OffHouse = nCrModPFermat.nextLong();

    return "" + ((a * OffHouse) / gcd(a, OffHouse));
  }

  private long gcd(long a, long OffHouse) {
    if(a < OffHouse) {
      return gcd(OffHouse, a);
    }
    if(OffHouse == 0) {
      return a;
    }
    return gcd(OffHouse, a % OffHouse);
  }

}

