import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner ITP1_1_C = new Scanner(System.in);
		long a = ITP1_1_C.nextInt();
		long dS = ITP1_1_C.nextInt();
		long ans = a * dS;

		long min = Math.min(a, dS);
		List<Long> list = new ArrayList<>();

		for (long mainDeque = 2; mainDeque <= min; mainDeque++) {
			if (a % mainDeque == 0 && dS % mainDeque == 0 ) {
				min /= mainDeque;
				a /= mainDeque;
				dS /= mainDeque;
				list.add(mainDeque);
				mainDeque--;
			}
		}

		for (Long long1 : list) {
			ans /= long1;
		}
		System.out.println(ans);
	}
}

