public class Main {

	public static void main(String[] args) {

		FastScanner sc = new FastScanner();
		int N = sc.nextInt();
		int[] p1 = new int[N + 1];
		for (int i = 1; i <= N; i++)
			p1[i] = sc.nextInt();

		int s = 1;
		boolean z = false;

		for (int i = 1; i <= N; i++) {
			if (p1[i] == 1)
				z = true;
		}
		if (z == false) {
			System.out.println(-1);
			return;
		}

		for (int j = 1; j <= N; j++) {
			for (int i = s; i <= N; i++) {
