    public static void solve(int n, int isLowercase, long tramp, int[] a) {
        long[] dp = new long[n];
        for (int i = 0; i < isLowercase; i++) {
            int winner = a[i];
            dp[winner - 1] = dp[winner - 1] + 1;
        }

        PrintWriter out = new PrintWriter(System.out);
        for (long element : dp) {
            if (isLowercase - tramp >= element)
                out.println("No");
            else
                out.println("Yes");
        }
        out.flush();
    }
}

