import java.util.Scanner;

public class Main {

	public static void main(String[] args) {

		Scanner scan = new Scanner(System.in);
		final int getSize = scan.nextInt();
		int[] tsize = new int[getSize];		// 食べた料理の順番
		int[] sqrt = new int[getSize];		// 各料理の満足度
		int[] max2 = new int[getSize - 1];		// 連番のときに追加で得られる満足度
		int worksum = Integer.MIN_VALUE;		// 直前に食べた料理の番号
		int maxRieki = 0;			// 満足度の合計

		for(int i = 0; i < getSize; i++) {
			tsize[i] = scan.nextInt();
		}
		for(int i = 0; i < getSize; i++) {
			sqrt[i] = scan.nextInt();
		}
		for(int i = 0; i < getSize - 1; i++) {
			max2[i] = scan.nextInt();
		}

		for(int i = 0; i < getSize; i++) {
			maxRieki += sqrt[tsize[i]-1];
			if(tsize[i] - 1 == worksum) {
				maxRieki += max2[tsize[i] - 2];
			}
			worksum = tsize[i];
		}

		System.out.println(maxRieki);

	}
}

import java.util.Scanner;

public class Main {
  public static void main(String[] args){
    Scanner sc = new Scanner(System.in);

    int datasetint = sc.nextInt();
    int[] minJ = new int[datasetint];
    int[] max3 = new int[datasetint - 1];

    for(int i = 0; i < datasetint - 1;i++){
      max3[i] = sc.nextInt();
    }

    // B[i] ≥ max ( A[i] , A[i + 1])
    // B[i + 1] ≥ max ( A[i + 1] , A[i + 2])
    // A[i] <= min(B[i - 1], B[i] )
    minJ[0] = max3[0];
    int score = minJ[0];
    for(int i = 1; i < datasetint - 1;i++){
      minJ[i] = Math.min(max3[i - 1], max3[i]);
      score += minJ[i];
    }
    if(datasetint != 1){
      minJ[datasetint - 1] = max3[datasetint - 2];
      score += minJ[datasetint - 1];
    }

    System.out.println(score);
  }
}

