	static class OriginScanner {
		StringTokenizer token;
		BufferedReader br;

		public OriginScanner() {
			br = new BufferedReader(new InputStreamReader(System.in));
		}

		String nextLine() {
			String str = null;
			try {
				str = br.readLine();
			}
			catch (IOException e) {
				System.out.println(e);
			}
			return str;
		}

		String next() {
			while (token == null || !token.hasMoreElements()) { 
