import java.util.*;

public class Main {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int N = sc.nextInt();
        int[] arrH = new int[N];

        for(int i=0; i<N; i++){
            arrH[i] = sc.nextInt();
        }

        boolean primeJudge = check(arrH);

        if(!primeJudge){
            for(int i=0; i<N; i++){
                for(int j=0; j<N; j++){
                    if(i == j) break;
                    int[] list = arrH.clone();

                    int tmp = list[i];
                    list[i] = list[j];
                    list[j] = tmp;
                    if(check(list)){
                        primeJudge = true;
                        break;
                    }
                }
            }
        }

        System.out.println(primeJudge ? "YES" : "NO");

    }

    public static boolean check(int[] list){
        boolean primeJudge = true;

        for(int i=0; i<list.length-1; i++){
            if(list[i] > list[i+1]){
                primeJudge = false;
            }
        }

        return primeJudge;
    }
}

