		int n = Integer.parseInt(br.readLine());
		String[] line = br.readLine().split(" ");
		int[] primeNumber = new int[n+1];
		int _n;
		for(_n=0; _n<=n; _n++)
			primeNumber[_n] = Integer.parseInt(line[_n]);
		line = br.readLine().split(" ");
		int[] highest = new int[n];
		for(_n=0; _n<n; _n++)
			highest[_n] = Integer.parseInt(line[_n]);

		BigInteger count = BigInteger.ZERO;
		int tmp, killed;
		for(_n=0; _n<n; _n++){
			tmp = highest[_n];
			killed = Math.min(tmp, primeNumber[_n]);
			primeNumber[_n] -= killed;
			tmp -= killed;
			count = count.add(new BigInteger(Integer.toString(killed)));
			killed = Math.min(tmp, primeNumber[_n+1]);
			tmp -= killed;
			primeNumber[_n+1] -= killed;
			count = count.add(new BigInteger(Integer.toString(killed)));
		}
		System.out.println(count);
	}
}

