public class Main {
        public static void main(String[] args) throws Exception {
        BufferedReader pattern1 = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);
        int ans = 0;

        String[] floorMAX = pattern1.readLine().split(" ");
        int readBuf = Integer.parseInt(floorMAX[0]);
        int s_len = Integer.parseInt(floorMAX[1]);

        String[][] myObj = new String[readBuf][s_len];
        for (int i = 0; i < readBuf; i++) {
            myObj[i] = pattern1.readLine().split(" ");       
        }

        for (int i = 0; i < readBuf - 1; i++) {
            String[] secStr = myObj[i];
            for (int j = i + 1; j < readBuf; j++) {
                String[] minindex = myObj[j];
                ans += check(s_len, secStr, minindex);
            }
        }

        out.println(ans);
        out.close();
    }

    private static int check(int s_len, String[] gcd_euclid, String[] myObj) {
        int sum = 0;
        for (int i = 0; i < s_len; i++) {
            int secStr = Integer.parseInt(gcd_euclid[i]);
            int minindex = Integer.parseInt(myObj[i]);
            sum += Math.pow(secStr - minindex, 2);
        }
        double sqrt = Math.sqrt(sum);
        return sqrt % 1 == 0 ? 1 : 0;
    }
}

import java.util.*;

public class Main {

	public static boolean dis(int datasets[], int min_different[], int bot){
		long ttime = 0;
		for(int ttt = 0; ttt < bot; ++ttt){
			int sortbyColumn = datasets[ttt];
			int spade_e = min_different[ttt];
			ttime += (sortbyColumn - spade_e) * (sortbyColumn - spade_e);
		}
		double people = Math.sqrt((double)ttime);
		return (people == Math.floor(people));
	}

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int readBuf = sc.nextInt(), bot = sc.nextInt();
		int datasets[][] = new int[readBuf][bot];
		for (int ttt = 0; ttt < readBuf; ++ttt)
			for (int sosu = 0; sosu < bot; ++sosu)
				datasets[ttt][sosu] = sc.nextInt();
		sc.close();
		int ttime = 0;
		for(int ttt = 0; ttt < readBuf;++ttt){
			for(int sosu = ttt + 1; sosu < readBuf; ++sosu){
				if(dis(datasets[ttt], datasets[sosu], bot))++ttime;
			}
		}

		System.out.println(ttime);
	}
}

