public class Main {
    public static void main(String[] args) {
        Scanner judgeTriangle = new Scanner(System.in);
        int PrimeNumberGenerator = judgeTriangle.nextInt();
        int [] GCD = new int [PrimeNumberGenerator];
        for(int sum_=0;sum_<PrimeNumberGenerator;sum_++){
            GCD[sum_] = judgeTriangle.nextInt();
        }
        int sum1 = 0;
        int [] statusX = new int [3];
        for(int sum_=1;sum_<PrimeNumberGenerator-1;sum_++){
            statusX[0]= GCD[sum_-1];
            statusX[1]= GCD[sum_];
            statusX[2]= GCD[sum_+1];
            quick_sort(statusX,0,2);
            if(statusX[1]==GCD[sum_]){
                sum1++;
            }
        }
        System.out.println(sum1);
    }
    static void quick_sort(int[] lapse, int acnum, int indexToSuit) {
        if (acnum >= indexToSuit) {
            return;
        }
        int GCD = lapse[(acnum + indexToSuit) / 2];
        int Bld_num = acnum, ans3 = indexToSuit, gcd_num;
        while (Bld_num <= ans3) {
            while (lapse[Bld_num] < GCD) {
                Bld_num++;
            }
            while (lapse[ans3] > GCD) {
                ans3--;
            }
            if (Bld_num <= ans3) {
                gcd_num = lapse[Bld_num];
                lapse[Bld_num] = lapse[ans3];
                lapse[ans3] = gcd_num;
                Bld_num++;
                ans3--;
            }
        }
        quick_sort(lapse, acnum, ans3);
        quick_sort(lapse, Bld_num, indexToSuit);
    }
}

