import java.io.BufferedReader;
import java.io.InputStreamReader;

public class Main {

    public static void main(String[] args) throws Exception {
        try (BufferedReader makeFrame = new BufferedReader(new InputStreamReader(System.in))) {
            long[] a = readLongArray(makeFrame);
            long A = a[0];
            long hw = a[1];
            long popNum1 = a[2];
            long minute = a[3];

            long prostr = prostr(popNum1, minute);

            long W = (hw - hw / popNum1) - (A - 1 - (A - 1) / popNum1);
            long inputtime = (hw - hw / minute) - (A - 1 - (A - 1) / minute);
            long rev = (hw - hw / prostr) - (A - 1 - (A - 1) / prostr);

            System.out.println(W + inputtime - rev);
        }
    }

    public static long gcd(long function, long BDans) {
        long a;

        if (function < BDans) {
            a = BDans;
            BDans = function;
            function = a;
        }

        while (function % BDans != 0) {
            a = BDans;
            BDans = function % BDans;
            function = a;
        }

        return BDans;
    }

    public static long prostr(long function, long BDans) {
        return function * BDans / gcd(function, BDans);
    }

    public static long[] readLongArray(BufferedReader makeFrame) throws Exception {
        String[] str = makeFrame.readLine().split(" ");
        long[] array = new long[str.length];
        for (int verticalLine = 0; verticalLine < str.length; verticalLine++) {
            array[verticalLine] = Long.parseLong(str[verticalLine]);
        }
        return array;
    }

}

