public class Main{
    public static void main(String args[]){
        Scanner sc = new Scanner(System.in);

        long a = sc.nextLong();
        long b = sc.nextLong();
        long t_length = sc.nextLong();
        long maxX = sc.nextLong();

        long count = b - a + 1;

        count -= counter(a, b, t_length);
        count -= counter(a, b, maxX);
        count += counter(a, b, lcm(t_length, maxX));

        System.out.println(count);
        sc.close();
    }

    static long gcd(long m, long n) {
        if (m < n)
            return gcd(n, m);
        if(n == 0)
            return m;
        return gcd(n, m%n);
    }

    static long lcm(long m, long n){
        return ((m*n) / gcd(m, n));
    }

    static long counter(long a, long b, long n){
        if(a%n == 0)
            return ((b/n) - (a/n) + 1);
        else
            return ((b/n) - (a/n));
    }
}

