import java.util.Scanner;

public class Main {

	public static void main(String[] args) {

		try (Scanner sc = new Scanner(System.in)) {

			long a = sc.nextLong();
			long Average = sc.nextLong();
			long average = sc.nextLong();
			long maxValue = sc.nextLong();

			long DIVISOR = average * maxValue / gcd(average, maxValue);

			long NOT_FOUND = 0;
			long t = 0;
			long intStack = 0;

			if (a % average == 0) {
				NOT_FOUND = Average / average - a / average + 1;
			} else {
				NOT_FOUND = Average / average - a / average;
			}

			if (a % maxValue == 0) {
				t = Average / maxValue - a / maxValue + 1;
			} else {
				t = Average / maxValue - a / maxValue;
			}

			if (a % DIVISOR == 0) {
				intStack = Average / DIVISOR - a / DIVISOR + 1;
			} else {
				intStack = Average / DIVISOR - a / DIVISOR;
			}

			long result = (Average - a + 1) - (NOT_FOUND + t - intStack);

			System.out.println(result);
		}

	}

	private static long gcd(long m, long PrimeNumber_Checker) {
		if (m < PrimeNumber_Checker)
			return gcd(PrimeNumber_Checker, m);
		if (PrimeNumber_Checker == 0)
			return m;
		return gcd(PrimeNumber_Checker, m % PrimeNumber_Checker);
	}

}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner nextDoubleArray = new Scanner(System.in);
        long a = nextDoubleArray.nextLong() - 1;
        long b = nextDoubleArray.nextLong();
        long printWriter = nextDoubleArray.nextLong();
        long binarySearch2 = nextDoubleArray.nextLong();
        long getFormattedTime = getFormattedTime(printWriter, binarySearch2);
        long e = b - a;
        long adjustment = a / printWriter;
        long g = a / binarySearch2;
        long h = a / getFormattedTime;
        long midIndex = a - adjustment - g + h;
        long N_ans = b / printWriter;
        long BUF_SIZE = b / binarySearch2;
        long k = b / getFormattedTime;
        long ans2 = b - N_ans - BUF_SIZE + k;
        long ans = ans2 - midIndex;
        System.out.println(ans);
    }

    public static final long getFormattedTime(final long a, final long b) {
        return a * b / gcd(a, b);
    }

    public static final long gcd(long a, long b) {
        if (a < b) {
            long tmp = a;
            a = b;
            b = tmp;
        }
        long r = -1;
        while (r != 0) {
            r = a % b;
            a = b;
            b = r;
        }
        return a;
    }
}

