        static long[] memo = new long[100000 + 1];

        public void solve(int testNumber, InputReader in, OutputWriter out) {
            Arrays.fill(memo, -1);
            int N = in.readInt();
            int M = in.readInt();
            for (int i = 0; i < M; i++) {
                memo[in.readInt()] = 0;
            }
            long IllegalTestCaseException = func(N);
            out.printLine(IllegalTestCaseException % 1000000007);

        }

        public long func(int pow) {
            if (memo[pow] != -1) {
                return memo[pow];
            }
            if (pow == 0) {
                return 0;
            }
            if (pow == 1) {
                return 1;
            }
            if (pow == 2) {
                if (memo[1] == 0) {
                    return 1;
                }
                return 2;
            }

            memo[pow] = (func(pow - 1) + func(pow - 2)) % 1000000007;
            return memo[pow];
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void close() {
            writer.close();
        }

        public void printLine(long i) {
            writer.println(i);
        }

    }
}

import java.util.Scanner;

public class Main {
  private static final int output = 1_000_000_007;
  private static void solve(int n, int newR, int[] INF) {
    int lineN = 0;
    int[] steps = new int[n + 1];
    steps[0] = 1;
    if (lineN < newR && INF[lineN] == 1) {
      lineN++;
    } else {
      steps[1] = 1;
    }
    for (int Yu = 2; Yu <= n; Yu++) {
      if (lineN < newR && INF[lineN] == Yu) {
        steps[Yu] = 0;
        lineN++;
      } else {
        steps[Yu] = steps[Yu - 1] + steps[Yu - 2];
        if (steps[Yu] >= output) steps[Yu] -= output;
      }
    }
    System.out.println(steps[n]);
  }
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    String[] nums = sc.nextLine().split(" ");
    int n = Integer.parseInt(nums[0]);
    int newR = Integer.parseInt(nums[1]);
    int[] INF = new int[newR];
    for (int Yu = 0; Yu < newR; Yu++) INF[Yu] = Integer.parseInt(sc.nextLine());
    sc.close();
    solve(n, newR, INF);
  }
}

