import java.util.Scanner;

public class Main {

	public static void main(String args[]) {

		Scanner sc = new Scanner(System.in);

		int N = sc.nextInt();
		int sumX = sc.nextInt();

		double p = 0;

		if(N < sumX) {

			for(int i=1;i<=N;i++) {
				if(sumX%i == 0 && ispow2(sumX/i)) {
					p += Math.pow(2, -1*((int)(log2(sumX/i))));
				}else {
					p += Math.pow(2, -1*((int)(log2(sumX/i) + 1)));
				}
			}

			p /= N;
		}else {
			for(int i=1;i<sumX;i++) {
				if(sumX%i == 0 && ispow2(sumX/i)) {
					p += Math.pow(2, -1*((int)(log2(sumX/i))));
				}else {
					p += Math.pow(2, -1*((int)(log2(sumX/i) + 1)));
				}
			}
			p /= N;

			p += (double)(N-sumX+1)/(double)N;
		}
		System.out.println(p);
	}

	public static boolean ispow2(int a) {
		int x = a & (a-1);
		if(x == 0) {
			return true;
		}else {
			return false;
		}
	}

	public static double log2(double a) {
		return Math.log(a)/Math.log(2);
	}
}

