class FastReaderR {
    byte[] buf = new byte[2048];
    int strc, total;
    InputStream in;

    FastReaderR(InputStream is) {
        in = is;
    }
    int scan() throws IOException {
        if (strc >= total) {
            strc = 0;
            total = in.read(buf);
            if (total <= 0) {
                return -1;
            }
        }
        return buf[strc++];
    }
    int nextInt() throws IOException {
        int c, val = 0;
        for (c = scan(); c <= 32; c = scan());
        boolean neg = c == '-';
        if (c == '-' || c == '+') {
            c = scan();
        }
        for (; c >= '0' && c <= '9'; c = scan()) {
            val = (val << 3) + (val << 1) + (c & 15);
        }
        return neg ? -val : val;
    }
    String next() throws IOException {
        int c;
        for (c = scan(); c <= 32; c = scan());
        StringBuilder sb = new StringBuilder();
        for (; c > 32; c = scan()) {
            sb.append((char) c);
        }
        return sb.toString();
    }
}

