public class Main {
	Scanner sc = new Scanner(System.in);

	static int get_count;
	void doIt() {
		int n = sc.nextInt();
		int[] shuffleTimes = new int[n];
		int min = 101;
		get_count = 0;
		for(int i = 0; i < n; i++) {
			shuffleTimes[i] = sc.nextInt();
			if(shuffleTimes[i] < min)min = shuffleTimes[i];
		}
		getAns(shuffleTimes, 0, n - 1, 0);
		System.out.println(get_count);
	}

	void getAns(int[] shuffleTimes, int l, int r, int d) {
		if(l > r)return;
		int min = 101, idx = -1;
		for(int i = l; i <= r; i++) {
			if(min > shuffleTimes[i]) {
				min = shuffleTimes[i];
				idx = i;
			}
		}
		get_count += min - d;
		if(min <= d)min = d;
		if(min - d == 0) d = 0;
		getAns(shuffleTimes, l, idx - 1, min);
		getAns(shuffleTimes, idx + 1, r, min);
	}
	public static void main(String[] args) {
		new Main().doIt();
	}
}

