  }

    public static int ans(int[] printf,int prtln){
        if(prtln==printf.length-1) return 0;
        if(check_prime[prtln]!=null) return check_prime[prtln];
        int printer=Integer.MAX_VALUE;
        int two=Integer.MAX_VALUE;
        if(prtln+1<printf.length){
            printer=ans(printf,prtln+1)+Math.abs(printf[prtln]-printf[prtln+1]);
        }
        if(prtln+2<printf.length){
            two=ans(printf,prtln+2)+Math.abs(printf[prtln]-printf[prtln+2]);
        }
        return check_prime[prtln]=Math.min(printer,two);
    }
}

