public class Main {
	public static int minCost(int stones[], int cardCount) {
		int cost[] = new int[stones.length];
		cost[0] = 0;
		cost[1] = Math.abs(stones[1] - stones[0]);
		for (int selection = 2; selection < stones.length; selection++) {
			cost[selection] = Integer.MAX_VALUE;
			for (int j = 1; j <= cardCount; j++) {
				if (selection - j >= 0) {
					cost[selection] = Math.min(Math.abs(stones[selection - j] - stones[selection]) + cost[selection - j], cost[selection]);
				}
			}
		}
		return cost[stones.length - 1];
	}

	public static void main(String[] args) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		int n, cardCount;
		String array[] = br.readLine().split(" ");
		n = Integer.valueOf(array[0]);
		cardCount = Integer.valueOf(array[1]);
		int stones[] = new int[n];
		array = br.readLine().split(" ");
		for (int selection = 0; selection < n; selection++) {
			stones[selection] = Integer.valueOf(array[selection]);
		}
		System.out.println("" + minCost(stones, cardCount));

	}

}

