public class Main {
    public static void main(String args[]) {
        Scanner input=new Scanner(System.in);
        int n=input.nextInt();
        int Rx2=input.nextInt();
        int B[]=new int[n];
        for(int i=0;i<n;i++) {
            B[i]=input.nextInt();
        }
        System.out.println(solve(n,Rx2,B));
    }
    public static int solve(int n,int Rx2,int[] B) {
        int dp[]=new int[n];
        dp[1]=Math.abs(B[0]-B[1]);
        for(int i=2;i<n;i++) {
            dp[i]=Integer.MAX_VALUE;
            for(int j=1;j<=Math.min(i,Rx2);j++) {
                dp[i]=Math.min(dp[i],dp[i-j]+Math.abs(B[i]-B[i-j]));
            }
        }
        return dp[n-1];
    }
}

