class Solver {

    private boolean check(char[] S, char[] strx, int si, int sj) {
        int N = S.length;
        for (int i = 0; i < N; i++) {
            if (S[(si + i) % N] !=  strx[(sj + i) % N]) {
                return false;
            }
        }
        return true;
    }

    public void run() {
        Scanner sc = new Scanner(System.in);
        char[] S = sc.next().toCharArray();
        char[] strx = sc.next().toCharArray();

        boolean rotatable = false;
        for (int i = 0; i < S.length; i++) {
            char ch = S[i];
            // find ch
            for (int j = 0; j < strx.length; j++) {
                if (ch == strx[j]) {
                    // start check
                    if (check(S, strx, i, j)) {
                        System.out.println("Yes");
                        return;
                    }
                }
            }
        }

        System.out.println("No");

        return;
    }

}

