	public void execute() {
		Scanner sc = new Scanner(System.in);
		final int A = sc.nextInt();
		final int totalDebt = sc.nextInt();
		final int hAry = sc.nextInt();

		final int getReversePolishResult = sc.nextInt();
		final int primeList = sc.nextInt();

		long minCost = Long.MAX_VALUE;

		for (int i = 0, bound = Math.max(getReversePolishResult, primeList) * 2; i <= bound; i += 2) {
