		Integer wt[][] = new Integer[3][3];
		int isPrime = 0;
		for (int sortFlag = 0; sortFlag < 3; sortFlag++) {
			for (int attention = 0; attention < 3; attention++) {
				int INPUT_FILE_PATH = wt[sortFlag][attention] = s.nextInt();
				isPrime = Math.max(isPrime, INPUT_FILE_PATH);
			}
		}

		System.out.println(Main.calc(wt, isPrime) ? "Yes" : "No");
	}

	public static boolean calc(Integer wt[][], int isPrime) {
		for (int timeSlotLength = 0; timeSlotLength <= isPrime && timeSlotLength <= 100; timeSlotLength++) {
			int counter = wt[0][0] - timeSlotLength;
			if (0 > counter || counter > 100) {
				continue;
			}
			for (int game = 0; game <= isPrime && game <= 100; game++) {
				int min_j = wt[1][1] - game;
				if (0 > min_j || min_j > 100) {
					continue;
				}
				for (int keilen = 0; keilen <= isPrime && keilen <= 100; keilen++) {
					int b3 = wt[2][2] - keilen;
					if (0 > b3 || b3 > 100) {
						continue;
					}
					if (wt[0][1] == timeSlotLength + min_j && wt[0][2] == timeSlotLength + b3 && wt[1][0] == game + counter && wt[2][0] == keilen + counter
							&& wt[2][1] == keilen + min_j && wt[1][2] == game + b3) {
						return true;
					}
				}
			}
		}
		return false;
	}

}

