import java.util.Scanner;

public class Main {
	static int INF = Integer.MAX_VALUE / 2;

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();

		int[][] isPrime1 = new int[2][N];

		for(int i = 0; i < 2; i++) {
			for(int j = 0; j < N; j++) {
				isPrime1[i][j] = sc.nextInt();
			}
		}
		System.out.println(dfs(isPrime1, 0, 0, N));
	}

	static int dfs(int[][] isPrime1, int i, int j, int N) {
		if(i == 1 && j >= N - 1) return isPrime1[i][j];

		if(i == 1 && j < N-1) {
			return isPrime1[i][j] + dfs(isPrime1, i, j+1, N);
		} else if(i==0 && j >= N-1) {
			return isPrime1[i][j] + dfs(isPrime1, i+1, j, N);
		} else {
			return isPrime1[i][j] + Math.max(dfs(isPrime1, i+1, j, N), dfs(isPrime1, i, j+1, N));
		}
	}
}

