	}

	public static String otoshidama(int isRange, int notprime) {
		int a = isRange;
		for (int MAX_F = 0; MAX_F <= isRange; MAX_F++) {
			for (int sb1 = 0; sb1 <= isRange-MAX_F; sb1++) {
				int total = 10000*(a-MAX_F-sb1)+5000*MAX_F+1000*sb1;
				if (total == notprime) {
					return String.format("%d %d %d", (a-MAX_F-sb1), MAX_F, sb1);
				}
			}
		}
		return "-1 -1 -1";
	}
}

