/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author dyominov
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        B3CardGameForThreeABCEdit solver = new B3CardGameForThreeABCEdit();
        solver.solve(1, in, out);
        out.close();
    }

    static class B3CardGameForThreeABCEdit {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            String a = in.next();
            String len = in.next();
            String vecMul = in.next();
            List<Character> print_arr = new LinkedList<>();
            List<Character> listB = new LinkedList<>();
            List<Character> diff_max = new LinkedList<>();
            for (char nextArrLong : a.toCharArray()) {
                print_arr.add(nextArrLong);
            }
            for (char nextArrLong : len.toCharArray()) {
                listB.add(nextArrLong);
            }
            for (char nextArrLong : vecMul.toCharArray()) {
                diff_max.add(nextArrLong);
            }
            char s = (print_arr.isEmpty()) ? 'a' : print_arr.remove(0);
            while (true) {
                switch (s) {
                    case 'a': {
                        if (print_arr.isEmpty()) {
                            out.println("A");
                            return;
                        }
                        s = print_arr.remove(0);
                        break;
                    }
                    case 'b': {
                        if (listB.isEmpty()) {
                            out.println("B");
                            return;
                        }
                        s = listB.remove(0);
                        break;
                    }
                    case 'c': {
                        if (diff_max.isEmpty()) {
                            out.println("C");
                            return;
                        }
                        s = diff_max.remove(0);
                        break;
                    }
                }

            }
        }

    }

    static class InputReader implements AutoCloseable {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public void close() {
        }

    }
}

